package android.view;import android.content.Context;import java.util.*;public class ViewGroup extends View{public static class LayoutParams{public static final int WRAP_CONTENT=-2,MATCH_PARENT=-1;public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public View findViewWithTag(Object tag){View own=super.findViewWithTag(tag);if(own!=null)return own;for(View v:children){View child=v.findViewWithTag(tag);if(child!=null)return child;}return null;}public View findViewById(int id){if(this.id==id)return this;for(View v:children){View x=v.findViewById(id);if(x!=null)return x;}return null;}public void offsetDescendantRectToMyCoords(View child,android.graphics.Rect rect){
 for(View v=child;v!=this;v=v.parent){if(v==null || v.parent==null)throw new IllegalArgumentException("not a descendant");int x=v.left-v.parent.scrollX,y=v.top-v.parent.scrollY;rect.left+=x;rect.right+=x;rect.top+=y;rect.bottom+=y;}}
public int indexOfChild(View v){return children.indexOf(v);}public int getChildCount(){return children.size();}public View getChildAt(int n){return children.get(n);}
public static class MarginLayoutParams extends LayoutParams{public int leftMargin,topMargin,rightMargin,bottomMargin,startMargin,endMargin;public MarginLayoutParams(int w,int h){super(w,h);}public void setMargins(int l,int t,int r,int b){leftMargin=l;topMargin=t;rightMargin=r;bottomMargin=b;}public void setMarginStart(int s){startMargin=s;}public void setMarginEnd(int e){endMargin=e;}public int getMarginStart(){return startMargin;}public int getMarginEnd(){return endMargin;}}
public ArrayList<View> children=new ArrayList<>();public ViewGroup(Context c){super(c);}public void addView(View v,LayoutParams p){children.add(v);v.parent=this;v.lp=p;if(attached)v.attach();}public void removeView(View v){if(!children.contains(v))return;children.remove(v);v.parent=null;if(v.attached)v.detach();}public void attach(){super.attach();for(View v:new ArrayList<>(children))v.attach();}public void detach(){for(View v:new ArrayList<>(children))v.detach();super.detach();}}